USE DATABASE MENDIX_APP;
USE SCHEMA AGENTS;

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.CHECK_COMPLIANCE("P_BL_ID" NUMBER(38,0))
RETURNS VARIANT
LANGUAGE SQL
COMMENT='Rule-based compliance scoring for one B/L. Writes COMPLIANCE_CHECK_RESULT and, unlike the previous version, also persists BILL_OF_LADING.COMPLIANCE_CHECK_PASSED so the check is observable afterwards.'
EXECUTE AS OWNER
AS '
DECLARE
  v_bl_number  VARCHAR;
  v_restricted BOOLEAN;
  v_dangerous  BOOLEAN;
  v_weight     FLOAT;
  v_issues     ARRAY;
  v_risk       NUMBER;
  v_compliant  BOOLEAN;
BEGIN
  SELECT b.BL_NUMBER,
         COALESCE(r.RESTRICTED, FALSE),
         COALESCE(b.IS_DANGEROUS_GOODS, FALSE),
         b.GROSS_WEIGHT_KGS
    INTO :v_bl_number, :v_restricted, :v_dangerous, :v_weight
  FROM MENDIX_APP.AGENTS.BILL_OF_LADING b
  LEFT JOIN (SELECT HS_CODE, MAX(IS_RESTRICTED OR REQUIRES_PERMIT) AS RESTRICTED
             FROM MENDIX_APP.AGENTS.HS_CODE_REFERENCE GROUP BY HS_CODE) r
         ON r.HS_CODE = b.HS_CODE
  WHERE b.BL_ID = :P_BL_ID;

  -- A SELECT ... INTO over zero rows leaves the variables NULL rather than
  -- raising, so this guard is reachable and is the only signal that the id
  -- does not exist.
  IF (v_bl_number IS NULL) THEN
    RETURN OBJECT_CONSTRUCT(''status'', ''NOT_FOUND'', ''bl_id'', :P_BL_ID);
  END IF;

  v_issues := ARRAY_CONSTRUCT_COMPACT(
      IFF(:v_restricted, ''RESTRICTED_HS_CODE'', NULL),
      IFF(:v_weight > 50000, ''OVERWEIGHT'', NULL),
      IFF(:v_dangerous, ''DANGEROUS_GOODS'', NULL));

  v_risk := IFF(:v_restricted, 30, 0)
          + IFF(:v_dangerous, 20, 0)
          + IFF(:v_weight > 50000, 10, 0);

  -- Dangerous goods raise the risk score but are lawful to ship when declared,
  -- so they are reported as an issue without failing the check. A restricted
  -- HS code is the only hard failure.
  v_compliant := NOT :v_restricted;

  INSERT INTO MENDIX_APP.AGENTS.COMPLIANCE_CHECK_RESULT
      (BL_ID, COMPLIANT, VIOLATIONS, RISK_SCORE, RULES_CHECKED)
  SELECT :P_BL_ID, :v_compliant, TO_JSON(:v_issues), :v_risk, 3;

  UPDATE MENDIX_APP.AGENTS.BILL_OF_LADING
     SET COMPLIANCE_CHECK_PASSED = :v_compliant
   WHERE BL_ID = :P_BL_ID;

  -- ''status'' and ''issues'' exist because the Streamlit page reads those keys.
  -- The old version returned only ''compliant'' and ''violations'', so the page fell
  -- through to its else branch and displayed every result as FAILED, and never
  -- rendered the violation list at all.
  RETURN OBJECT_CONSTRUCT(
      ''status'',     IFF(:v_compliant, ''PASS'', ''FAIL''),
      ''bl_number'',  :v_bl_number,
      ''compliant'',  :v_compliant,
      ''risk_score'', :v_risk,
      ''issues'',     :v_issues,
      ''violations'', :v_issues,
      ''rules_checked'', 3);
END;
';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.CLASSIFY_BATCH("P_LIMIT" NUMBER(38,0) DEFAULT 100)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS 'BEGIN
  LET classified_count NUMBER := 0;
  UPDATE MENDIX_APP.AGENTS.BILL_OF_LADING t
  SET CONTAINER_TYPE = SNOWFLAKE.CORTEX.COMPLETE(''mistral-large2'',
    ''Classify into ONE word (Electronics/Textiles/Food/Chemicals/Machinery/Automotive/Metals/Consumer/Pharma/Other): '' || t.COMMODITY_DESCRIPTION
  )
  WHERE t.BL_ID IN (
    SELECT BL_ID FROM MENDIX_APP.AGENTS.BILL_OF_LADING WHERE CONTAINER_TYPE IS NULL OR CONTAINER_TYPE = '''' LIMIT :P_LIMIT
  );
  classified_count := SQLROWCOUNT;
  INSERT INTO MENDIX_APP.AGENTS.AI_CALL_LOG (CALL_TIMESTAMP, MODEL_NAME, CONTEXT, CALL_STATUS, RESPONSE)
  SELECT CURRENT_TIMESTAMP(), ''mistral-large2'', ''CLASSIFY_BATCH'', ''SUCCESS'', :classified_count::VARCHAR || '' classified'';
  RETURN :classified_count::VARCHAR || '' commodities classified'';
END';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.CLASSIFY_COMMODITY("P_BL_ID" NUMBER(38,0))
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS 'BEGIN
  LET commodity VARCHAR;
  LET classification VARCHAR;
  commodity := (SELECT COMMODITY_DESCRIPTION FROM MENDIX_APP.AGENTS.BILL_OF_LADING WHERE BL_ID = :P_BL_ID AND COMMODITY_DESCRIPTION IS NOT NULL AND COMMODITY_DESCRIPTION != '''' LIMIT 1);
  IF (:commodity IS NULL) THEN
    RETURN ''No commodity description found for BL_ID '' || :P_BL_ID::VARCHAR;
  END IF;
  BEGIN
    classification := (SELECT SNOWFLAKE.CORTEX.COMPLETE(''mistral-large2'',
      ''Classify into ONE category (Electronics/Textiles/Food/Chemicals/Machinery/Automotive/Raw_Materials/Consumer_Goods/Pharmaceuticals/Other). Return ONLY the category. Commodity: '' || :commodity));
  EXCEPTION
    WHEN OTHER THEN classification := ''Other'';
  END;
  classification := TRIM(REPLACE(REPLACE(:classification, ''"'', ''''), ''.'', ''''));
  UPDATE MENDIX_APP.AGENTS.BILL_OF_LADING SET CONTAINER_TYPE = :classification WHERE BL_ID = :P_BL_ID;
  INSERT INTO MENDIX_APP.AGENTS.AI_CALL_LOG (CALL_TIMESTAMP, MODEL_NAME, CONTEXT, CALL_STATUS, PROMPT, RESPONSE)
  SELECT CURRENT_TIMESTAMP(), ''mistral-large2'', ''CLASSIFY_COMMODITY'', ''SUCCESS'', :commodity, :classification;
  RETURN :classification;
END';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.CLASSIFY_DOCUMENT_TEXT("P_DOC_TEXT" VARCHAR)
RETURNS OBJECT
LANGUAGE SQL
EXECUTE AS OWNER
AS '
DECLARE
    V_PROMPT VARCHAR; V_RESPONSE VARIANT; V_DOC_TYPE VARCHAR; V_CONFIDENCE FLOAT;
BEGIN
    V_PROMPT := ''You are a document classifier for logistics. Classify this document into one of these types: BILL_OF_LADING, COMMERCIAL_INVOICE, PACKING_LIST, CERTIFICATE_OF_ORIGIN, CUSTOMS_DECLARATION, OTHER. Return JSON with "doc_type" and "confidence" (0-100). Document text: '' || P_DOC_TEXT;
    V_RESPONSE := (CALL AI_COMPLETE_WITH_RETRY(V_PROMPT, ''llama3-8b'', 2));
    V_DOC_TYPE := V_RESPONSE:doc_type::VARCHAR;
    V_CONFIDENCE := V_RESPONSE:confidence::FLOAT;
    INSERT INTO AI_CLASSIFICATION_CACHE (DOC_TEXT, DOC_TYPE, CONFIDENCE_SCORE, MODEL_NAME)
    VALUES (SUBSTRING(P_DOC_TEXT, 1, 5000), V_DOC_TYPE, V_CONFIDENCE, ''llama3-8b'');
    RETURN OBJECT_CONSTRUCT(''doc_type'', V_DOC_TYPE, ''confidence'', V_CONFIDENCE);
END;
';

